import numpy as np
import math

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation diversity: how many distinct colours are among a candidate's coloured neighbours, minus the average such count over the candidates. Measures whether a vertex is unusually constrained by many different colours."""
    k = len(degree)
    if k == 0:
        return np.zeros(0)
    # number of colours present among the candidate's coloured neighbours
    distinct = (neighbor_colors > 0).sum(axis=1).astype(float)
    # normalise by total colours used so far; if none, all zero
    c = neighbor_colors.shape[1]
    if c > 0:
        norm = distinct / float(c)
    else:
        norm = np.zeros(k)
    # subtract mean over candidates -> contrast signal
    mean = norm.mean() if k > 0 else 0.0
    return np.clip(norm - mean, -1.0, 1.0)

