import math

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation weighted by how confined a colour is: for each candidate, the sum over colours already used by neighbours of (1 - colour_popularity_share), highlighting vertices that block scarce colours."""
    k = neighbor_colors.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    total_vertices = k + color_sizes.sum()
    share = color_sizes.astype(float) / max(total_vertices, 1)
    scarcity = 1.0 - share  # small colours are scarce and precious
    blocked = neighbor_colors > 0
    neighbours_used = neighbor_colors.sum(axis=1).astype(float)
    weighted = (blocked * scarcity[None, :]).sum(axis=1)
    return weighted / np.maximum(neighbours_used, 1.0)

