def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation degree weighted by how close each present colour is to being blocked: sum over colours of (1 - 1/(1+count)) / max(c,1)."""
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(neighbor_colors.shape[0])
    counts = neighbor_colors.astype(float)
    # each colour contributes more when the candidate has more neighbours of that colour,
    # saturating towards 1; distinct colours still each add, but multiplicity now matters
    contrib = counts / (1.0 + counts)
    return contrib.sum(axis=1) / max(c, 1)

