def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Negative size of the smallest feasible colour class (first zero column, or 1 if new colour), divided by n."""
    k = len(degree)
    c = neighbor_colors.shape[1]
    n = k + int(color_sizes.sum())
    if c == 0:
        return np.zeros(k)
    z = (neighbor_colors == 0)
    has = z.any(axis=1)
    idx = z.argmax(axis=1)
    size = np.where(has, color_sizes[idx], 1)
    return -size / max(n, 1)

