def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Negative fraction of candidates whose last free colour would be consumed by this candidate."""
    k = len(degree)
    c = neighbor_colors.shape[1]
    if k == 0:
        return np.zeros(0)
    if c == 0:
        return np.zeros(k)
    zero = (neighbor_colors == 0)
    deg_free = zero.sum(1)
    only = deg_free == 1
    only_idx = np.argmax(zero, axis=1)
    target = np.where(deg_free > 0, only_idx, c)
    same = (only_idx[None, :] == target[:, None]) & only[None, :]
    block = (adjacency.astype(float) * same).sum(1)
    return -block / float(k)

