def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation (fraction of present colours blocked) times (1 - target class size / n), new colour counted as size n."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if k == 0:
        return np.zeros(0)
    if c == 0:
        return np.zeros(k)
    n = float(k) + float(color_sizes.sum())
    zero = (neighbor_colors == 0)
    has = zero.any(1)
    first = np.argmax(zero, axis=1)
    target = np.where(has, first, c)
    sat = (neighbor_colors > 0).sum(1).astype(float) / float(c)
    sizes = np.concatenate([color_sizes.astype(float), [n]])
    s = sizes[target]
    return sat * (1.0 - s / n)

