def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Uncoloured degree (normalised by k) divided by 1 + saturation fraction."""
    k = len(degree)
    c = neighbor_colors.shape[1]
    uncol = adjacency.sum(1).astype(float) / max(k, 1)
    if c == 0:
        return uncol
    sat = (neighbor_colors > 0).sum(1).astype(float) / float(c)
    return uncol / (1.0 + sat)

