def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Distinct colours among a candidate's coloured neighbours, divided by (1 + its coloured degree)."""
    colored_deg = degree.astype(float) - adjacency.sum(axis=1).astype(float)
    if neighbor_colors.shape[1] == 0:
        distinct = np.zeros(neighbor_colors.shape[0], dtype=float)
    else:
        distinct = (neighbor_colors > 0).sum(axis=1).astype(float)
    return distinct / (1.0 + colored_deg)

