def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Count of blocked uncoloured neighbours, but only neighbours that are 'cheap' to leave blocked: a blocked neighbour weighted by 1/(1+its uncoloured degree), so isolated-ish blocked vertices count more (they can wait), summed and normalised by k."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k, dtype=float)
    # blocked: cannot take any existing colour
    free = (neighbor_colors == 0).any(axis=1)
    blocked = (~free).astype(float)
    nb = adjacency.astype(float)
    udeg = nb.sum(axis=1)
    # weight blocked neighbours inversely by their uncoloured degree (low degree -> can be postponed)
    weight = blocked / (1.0 + udeg)
    return (nb @ weight) / max(k, 1)

