def feature(neighbor_colors, adjacency, degree, color_sizes):
    """For each candidate, the number of its uncoloured neighbours that are blocked (no existing colour free), but only counting blocked neighbours that would need a brand-new colour and whose own uncoloured-degree is high: weighted blocked-neighbour count divided by candidate's own uncoloured degree, normalised to [-1, 1] via a squashing transform."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k, dtype=float)
    blocked = (~((neighbor_colors == 0).any(axis=1))).astype(float)
    nb = adjacency.astype(float)
    deg_u = nb.sum(axis=1)
    # weight each blocked neighbour by how many uncoloured neighbours it has (it will spread the constraint)
    spread = nb @ (blocked * deg_u)
    # candidate's own uncoloured degree tempers its exposure
    raw = spread / (deg_u + 1.0)
    # squash to [-1, 1]
    return raw / (1.0 + np.abs(raw))

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Sum over uncoloured neighbours j of adjacency[i,j]*blocked_j*deg_u(j), divided by k*max(deg_u)."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    blocked = (neighbor_colors != 0).all(axis=1).astype(np.float64)
    deg_u = adjacency.sum(axis=1).astype(np.float64)
    mass = blocked * deg_u
    vals = adjacency.astype(np.float64) @ mass
    denom = max(k * deg_u.max(), 1.0)
    return vals / denom
